from produire import produire
from format_lecon import paras,table,steps
parts=[
('Une {tumeur maligne nasosinusienne peut provoquer une obstruction nasale}. Le ronflement est alors un effet possible du rétrécissement. Il est peu spécifique et ne constitue pas le signe diagnostique principal.',paras('Les cancers des cavités nasales et des sinus regroupent plusieurs histologies. La localisation et le type de tumeur déterminent le bilan et le traitement.', 'Cette leçon ne transpose pas un protocole de cancer du nasopharynx à un cancer des sinus. Une masse bénigne peut aussi obstruer ; la malignité exige une confirmation adaptée.')),
('Le {contexte est rare mais le retard diagnostique compte}. Une obstruction peut longtemps ressembler à une maladie inflammatoire. Les expositions professionnelles orientent l’interrogatoire.',paras('Le CHUV mentionne notamment poussières de bois, produits du cuir et des textiles, formaldéhyde et tabagisme. Les associations varient selon les histologies et ne sont pas présentes chez tous les patients.', 'Aucun classement de fréquence des tumeurs chez les ronfleurs n’est proposé. La raison de les rechercher est surtout la présence de signes atypiques ou progressifs.')),
('La {croissance locale peut atteindre des structures voisines sensibles}. Nez et sinus sont proches de l’orbite, de la base du crâne et de trajets nerveux. Cette anatomie explique les signes d’extension.',paras('Une obstruction et un écoulement peuvent précéder les signes plus spécifiques. Douleur faciale, trouble de sensibilité, diplopie ou baisse visuelle peuvent refléter une atteinte locale avancée.', 'L’extension n’est pas déduite de l’intensité du ronflement. L’imagerie et l’endoscopie précisent les limites et les risques avant le traitement.')),
('Les {alarmes sont une obstruction unilatérale persistante, du sang et des signes neurologiques ou visuels}. Elles demandent un avis ORL rapide. Une complication visuelle ou neurologique impose une évaluation urgente.',paras('ESMO–EURACAN recommande un examen ORL complet, avec endoscopie, devant des symptômes nasosinusiens persistant au moins trois semaines. Ce repère ne signifie pas qu’il faille attendre trois semaines si un signe d’alarme est déjà présent.', 'Un saignement important ou une difficulté respiratoire aiguë demande une prise en charge immédiate. Éviter les manipulations ou prélèvements non planifiés d’une masse potentiellement très vascularisée.')),
('L’{anamnèse cherche progression, latéralité et signes associés}. Demander obstruction, épistaxis, douleur, odorat et sensation d’oreille bouchée. Rechercher diplopie, trouble sensitif et masse cervicale.',paras('Préciser durée, évolution sous traitement, expositions professionnelles et antécédents. Une amélioration transitoire avec un spray n’exclut pas une lésion sous-jacente.', 'Évaluer alimentation, poids, état général et retentissement psychologique. Si des apnées sont suspectées, informer l’équipe pour le bilan et la sécurité anesthésique.')),
('L’{examen doit visualiser la cavité nasale et évaluer les voisinages}. L’endoscopie ORL identifie le site suspect. Rechercher anomalies oculaires, neurologiques et ganglionnaires.',paras('Une simple inspection antérieure peut manquer une lésion profonde. L’examen de la bouche, du visage, de la sensibilité et des mouvements oculaires complète le bilan.', 'Le prélèvement relève d’une stratégie spécialisée. Une endoscopie d’observation et une biopsie ne sont pas nécessairement effectuées dans les mêmes conditions de sécurité.')),
('L’{approche syndromique compare inflammation et lésion focale}. Une tumeur ne se distingue pas toujours par un symptôme isolé. La persistance et l’asymétrie renforcent la suspicion.',table(['Présentation','Question'],[['Prurit bilatéral lié aux expositions.','Rhinite allergique ?'],['Obstruction bilatérale chronique avec polypes réguliers.','Polypose inflammatoire ?'],['Obstruction progressive unilatérale, saignement, douleur.','Tumeur à exclure.'],['Signes visuels ou nerveux.','Extension ou complication nécessitant une évaluation urgente.'] ])),
('Le {diagnostic positif repose sur l’histologie avec le bilan radiologique}. Une image suspecte ne suffit pas à nommer le type tumoral. Les formes rares peuvent nécessiter une expertise anatomopathologique.',paras('ESMO–EURACAN recommande une confirmation histopathologique complétée selon le cas par immunohistochimie et études moléculaires. Une relecture experte est particulièrement importante pour les tumeurs peu différenciées ou de haut grade.', 'La recommandation citée concerne plusieurs cancers nasosinusiens mais ne couvre pas tous les mélanomes muqueux ou sarcomes. Leur traitement ne doit pas être extrapolé à partir d’un schéma commun.')),
('Les {examens déterminent extension et sécurité du prélèvement}. L’imagerie précède idéalement la biopsie. Elle examine notamment orbite, base du crâne et diffusion périnerveuse.',paras('La tomodensitométrie analyse bien les structures osseuses ; l’IRM apporte des informations sur tissus mous, orbite, dure-mère et trajets nerveux. Leur choix et leur association dépendent de la question.', 'Le bilan ganglionnaire et à distance est adapté à l’histologie et au stade. La biopsie peut être réalisée en consultation ou en milieu opératoire selon risque hémorragique et extension, avec guidage endoscopique lorsque pertinent.')),
('L’{algorithme organise rapidement le diagnostic et la décision spécialisée}. Une suspicion ne doit pas être diluée dans des essais répétés de sprays. Le traitement dépend ensuite du type et de l’extension.',steps('Repérer urgence visuelle, neurologique, respiratoire ou hémorragique.', 'Adresser rapidement pour examen ORL et endoscopie.', 'Réaliser l’imagerie adaptée puis organiser le prélèvement en sécurité.', 'Confirmer histologie et stade en équipe spécialisée.', 'Discuter traitement, réhabilitation et suivi multidisciplinaires.')),
('La {prise en charge suisse relève d’une équipe d’oncologie ORL}. Chirurgie, radiothérapie et traitements systémiques sont discutés selon la tumeur. Le traitement du bruit n’est pas l’objectif oncologique.',paras('Le CHUV décrit un parcours coordonné au centre des tumeurs ORL. ESMO–EURACAN insiste sur la possibilité d’une résection complète avec marges adéquates lorsque la chirurgie est choisie ; une résection partielle n’est pas un substitut oncologique équivalent.', 'Selon histologie, extension et opérabilité, une radiothérapie ou une combinaison de traitements peut être retenue. Aucun protocole universel de chimiothérapie ni aucune dose empirique ne sont proposés pour ce groupe hétérogène.', 'Prévoir soins de support, nutrition, réhabilitation et accompagnement. Les contraintes anesthésiques et les troubles respiratoires du sommeil associés sont transmis à l’équipe.')),
('La {prévention vise notamment les expositions évitables et la surveillance}. Réduire le tabagisme et appliquer les protections professionnelles adaptées. Le suivi est individualisé selon le cancer et les traitements.',paras('Contrôler récidive, séquelles, fonction nasale, vision, douleur et qualité de vie. Une obstruction ou un saignement nouveau après traitement doit être signalé.', 'La disparition du ronflement n’est pas un marqueur de rémission tumorale. Inversement, un bruit résiduel peut avoir une autre origine et mérite un bilan adapté.')),
('Le {point clé est de ne pas banaliser une obstruction unilatérale progressive}. L’examen ORL et la confirmation histologique orientent le traitement. La gravité ne se mesure pas au niveau sonore nocturne.',paras('Aucun médicament antironflement ne doit retarder le parcours diagnostique. Anatomie, histologie et extension gouvernent une prise en charge spécialisée.'))]
quiz=[('Le ronflement est-il un signe spécifique de cancer ?','Non.'),('Quelle association doit alerter ?','Obstruction unilatérale persistante avec épistaxis ou douleur.'),('Une baisse visuelle peut-elle attendre trois semaines ?','Non, le signe d’alarme impose une évaluation urgente.'),('Les expositions au bois doivent-elles être recherchées ?','Oui.'),('Une amélioration transitoire sous spray exclut-elle une tumeur ?','Non.'),('Une inspection antérieure normale suffit-elle ?','Non, une lésion profonde peut nécessiter l’endoscopie.'),('Une masse doit-elle être biopsiée à l’aveugle ?','Non.'),('Quand réalise-t-on idéalement l’imagerie par rapport à la biopsie ?','Avant, pour préciser extension et sécurité.'),('Quel examen confirme le type tumoral ?','L’analyse histopathologique, complétée selon indication.'),('L’IRM peut-elle étudier une diffusion périnerveuse ?','Oui.'),('Tous les cancers nasosinusiens reçoivent-ils le même traitement ?','Non.'),('Une résection partielle est-elle équivalente à une résection complète oncologique ?','Non.'),('La disparition du bruit prouve-t-elle une rémission ?','Non.'),('Les symptômes nouveaux après traitement doivent-ils être signalés ?','Oui.')]
produire(10,parts,quiz,(3,8,13))
